const input=$json.body??$json;
const strategy=String(input.strategy??'').toLowerCase();
const classification=String(input.classification??'').toLowerCase();
const dealId=input.deal_id??input.dealId,leadId=input.lead_id??input.leadId,propertyId=input.property_id??input.propertyId;
const protectedMao=Number(input.protected_mao??input.dynamic_mao??input.mao??0);
const sellerAsk=Number(input.seller_ask??input.counteroffer_amount??0);
const currentOffer=Number(input.current_offer??input.offer_amount??0);
const sourceKey=input.decision_idempotency_key??input.idempotency_key;
const dnc=Boolean(input.dnc||input.do_not_contact||input.opted_out);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
let decision='human_review',route='WF-126',reason='Insufficient evidence for an automated negotiation decision.',revisedOffer=0;
if(strategy==='stop'||dnc){decision='stop';route='WF-126';reason='DNC/opt-out or stop strategy overrides automated negotiation.'}
else if(blockers.length){decision='human_review';route='WF-126';reason='Operational blockers require controlled human handling.'}
else if(strategy==='reengage'||classification==='rejection'){decision='reengage';route='WF-345';reason='Seller is not ready to accept; return to controlled re-engagement.'}
else if(strategy==='prepare_acceptance_or_contract'&&sellerAsk>0&&protectedMao>0&&sellerAsk<=protectedMao){decision='contract_ready';route='WF-150';reason='Seller position is within protected MAO; prepare contract package.'}
else if((strategy==='evaluate_near_mao_counter'||strategy==='hold_mao'||strategy==='continue_negotiation')&&protectedMao>0){
 if(sellerAsk>0&&sellerAsk<=protectedMao){decision='accept_or_contract';route='WF-150';reason='Seller ask is within protected MAO.'}
 else if(currentOffer>0&&currentOffer<=protectedMao){revisedOffer=Math.round(Math.min(currentOffer,protectedMao)*100)/100;decision='revised_offer';route='WF-366';reason='Seller ask exceeds protected MAO; maintain an offer within protected economics.'}
 else if(sellerAsk>protectedMao){decision='walk_away';route='WF-345';reason='Seller ask exceeds protected MAO and no safe revised offer is available.'}
}
else if(strategy==='respond_and_continue'){decision='respond';route='WF-365';reason='Seller needs clarification or a call before an economic decision.'}
const valid=Boolean(dealId&&leadId&&propertyId&&sourceKey);
if(!valid&&decision!=='stop'&&decision!=='human_review'){decision='reconcile';route='WF-360';reason='Required identity/idempotency fields are missing.'}
const key=sourceKey?\`${sourceKey}:decision:${decision}:${revisedOffer}\`:null;
return [{json:{workflow:'WF-372',decision,route,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,strategy,classification,seller_ask:sellerAsk,current_offer:currentOffer,protected_mao:protectedMao,revised_offer:revisedOffer,mao_protected:true,identity_valid:valid,decision_idempotency_key:key,audit_event:'negotiation_decision_revised_offer_walkaway_contract'}}];
